source('mp10_hypothesis_followup_v2/scripts/common.R')
b<-qread(file.path(OLD,'objects/pseudobulk.qs'),nthreads=1);p<-as.data.table(b$profiles);m<-old('pseudobulk_membership.tsv.gz');out<-list();check<-function(n,v){out[[n]]<<-data.table(check=n,passed=isTRUE(v));stopifnot(v)}
check('raw_counts_nonnegative_integer',all(b$counts@x>=0&b$counts@x==round(b$counts@x)));check('features_unique',!anyDuplicated(rownames(b$counts)));check('profiles_unique',!anyDuplicated(p$profile_id));check('profile_order',identical(colnames(b$counts),p$profile_id));check('detected_alignment',identical(dimnames(b$counts),dimnames(b$detected_cells)));check('detected_cells_nonnegative_integer',all(b$detected_cells@x>=0&b$detected_cells@x==round(b$detected_cells@x)));check('membership_unique_within_profile',!anyDuplicated(m[,.(profile_id,barcode)]));n<-m[,.N,by=profile_id];check('membership_counts_match',all(n$N==p$n_cells[match(n$profile_id,p$profile_id)]));check('raw_total_counts_match',all(Matrix::colSums(b$counts)==p$total_counts));check('detection_bound',all(Matrix::colSums(b$detected_cells>0)==p$detected_genes));
for(s in unique(m$sample_uid)){z<-m[sample_uid==s];L<-z[profile_type=='L50',barcode];H<-z[profile_type=='H50',barcode];H10<-z[profile_type=='H10',barcode];H05<-z[profile_type=='H05',barcode];check(paste0('disjoint_L50_H50_',s),length(intersect(L,H))==0);check(paste0('nested_High_',s),all(H05%in%H10)&&all(H10%in%H));check(paste0('Epi_all_members_',s),setequal(z[profile_type=='Epi_all',barcode],c(L,H)));check(paste0('Epi_all_raw_counts_',s),all(b$counts[,paste0(s,'|Epi_all')]==b$counts[,paste0(s,'|L50')]+b$counts[,paste0(s,'|H50')]))}
put(rbindlist(out),'counts_membership_validation.tsv');cat('COUNTS CHECKS',length(out),'passed\n')
